{
  "is front page": true,
  "content": {
    "logo large": "https://hugeampkpncms.org/sites/default/files/images/mouseGeneSet/mouse_gene_set_front.svg",
    "color primary": "#6b86b1",
    "color secondary": "#293266",
    "tagline": "Discover mouse phenotypes genetically linked to human traits – using statistical enrichment, not just similarity",
    "search enabled": true,
    "single search version":"cfde",
    "single search": {
      "version": "cfde",
      "search instruction": "Search gene or disease",
      "search examples": [
        {
          "parameter": "gene",
          "value": "BDH2",
          "url": "/r/mouse_gene_set_browser_gene?gene=BDH2"
        }
      ],
      "search parameters": [
        {
          "parameter": "gene",
          "label": "GENE",
          "values": "kp genes",
          "options": [
            {
              "summary id": "gene_info",
              "summary label": "See a summary of gene function",
              "sections": [
                {
                  "id": "bi_gene_summaries",
                  "header": "Gene summaries",
                  "data point": {
                    "type": "bioindex",
                    "url": "https://bioindex-dev.hugeamp.org/api/bio/query/gene-summaries?q=$gene",
                    "parameters": [
                      "gene"
                    ],
                    "parameters type": "replace",
                    "data type": "bioindex"
                  },
                  "summary text": "Gene summaries",
                  "summary columns": [
                    {
                      "field": "gene",
                      "header": "Gene"
                    },
                    {
                      "field": "abstract",
                      "header": "Summary"
                    }
                  ],
                  "summary rows": 1
                }
              ]
            },
            {
              "summary id": "gene_set_browser",
              "summary label": "Preview top gene set analysis results",
              "sections": [
                {
                  "id": "gene_set_phenotypes",
                  "header": "most associated phenotypes",
                  "data point": {
                    "type": "bioindex",
                    "url": "https://cfde-dev.hugeampkpnbi.org/api/bio/query/pigean-overall-gene?q=$gene",
                    "continue url": "https://cfde-dev.hugeampkpnbi.org/api/bio/cont?token=",
                    "parameters": [
                      "gene"
                    ],
                    "parameters type": "replace",
                    "data type": "bioindex"
                  },
                  "pre filters": [
                    {
                      "field": "source",
                      "type": "contains",
                      "values": [
                        "mouse",
                        "komp"
                      ]
                    }
                  ],
                  "summary text": "Traits with genetic support",
                  "summary columns": [
                    {
                      "field": "phenotype_name",
                      "header": "Phenotype"
                    },
                    {
                      "field": "phenotype",
                      "header": "Phenotype ID",
                      "format": {
                        "type": "link",
                        "link": "/r/mouse_gene_set_browser_phenotype?phenotype=$phenotype",
                        "parameters": [
                          "phenotype"
                        ]
                      }
                    },
                    {
                      "field": "gene_set",
                      "header": "Gene set",
                      "format": {
                        "type": "link",
                        "link": "/r/mouse_gene_set_browser_gene_set?geneSet=$gene_set",
                        "parameters": [
                          "gene_set"
                        ]
                      }
                    },
                    {
                      "field": "source",
                      "header": "Source",
                      "format": {
                        "type": "link",
                        "link": "/r/mouse_gene_set_browser_source?source=$source",
                        "parameters": [
                          "source"
                        ]
                      }
                    },
                    {
                      "field": "beta",
                      "header": "Effect"
                    },
                    {
                      "field": "beta_uncorrected",
                      "header": "Effect(uncorrected)"
                    },
                    {
                      "field": "gene",
                      "header": "Gene",
                      "format": {
                        "type": "link",
                        "link": "/r/mouse_gene_set_browser?gene=$gene",
                        "parameters": [
                          "gene"
                        ]
                      }
                    }
                  ],
                  "summary rows": 20
                }
